insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('fca5fea5-bfcf-4e40-8174-17c5b1845020', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Differential-Equation Models, Direction Fields, and Well-Posed Problems', 'Differential equations turn local laws of change into predictions about an evolving system. This opening unit teaches students to formulate models, read solution geometry, and ask whether an initial-value problem has a meaningful and unique solution before calculating.', 0),
  ('4debd3b3-5354-4ccb-a443-656f0f993c57', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'fca5fea5-bfcf-4e40-8174-17c5b1845020', 'subtopic'::public.curated_course_node_type, 'Modeling and classification', 'Classification reveals what kind of mathematical object is being studied and which tools might apply.', 0),
  ('e2593f80-7c16-4c84-8f1e-5953414d6f2a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '4debd3b3-5354-4ccb-a443-656f0f993c57', 'concept'::public.curated_course_node_type, 'Dependent and independent variables, parameters, state variables, and units', null, 0),
  ('ab72e0a0-98e1-411f-9832-da299fdf21aa', '5948bdf7-dcf7-4f02-b49d-13d431675423', '4debd3b3-5354-4ccb-a443-656f0f993c57', 'concept'::public.curated_course_node_type, 'Ordinary versus partial differential equations, order, linearity, autonomy', null, 1),
  ('201d558a-e791-460d-916e-bd51c28b0a6b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '4debd3b3-5354-4ccb-a443-656f0f993c57', 'concept'::public.curated_course_node_type, 'Initial-value and boundary-value problems', null, 2),
  ('e5ceeb73-a58a-4d05-95a9-cfff164b332a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '4debd3b3-5354-4ccb-a443-656f0f993c57', 'concept'::public.curated_course_node_type, 'Translating conservation, balance, force, circuit, kinetic, and population laws into equations', null, 3),
  ('8665de63-a7a5-47ac-9ec7-f314c44f514f', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'fca5fea5-bfcf-4e40-8174-17c5b1845020', 'subtopic'::public.curated_course_node_type, 'Direction fields and solution curves', 'A direction field displays the slopes prescribed by a first-order equation and reveals behavior even when no closed form exists.', 1),
  ('a1828d3d-db91-4f6f-8a7f-e2a8ea1fe8fa', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8665de63-a7a5-47ac-9ec7-f314c44f514f', 'concept'::public.curated_course_node_type, 'Isoclines, nullclines, integral curves, and families of solutions', null, 0),
  ('ebbc36cd-50c0-45eb-8b18-93f2ce56f1fc', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8665de63-a7a5-47ac-9ec7-f314c44f514f', 'concept'::public.curated_course_node_type, 'Reading monotonicity, equilibria, and long-run trends from a field', null, 1),
  ('622d35a2-9114-4318-9164-fbe54ba0aa1b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8665de63-a7a5-47ac-9ec7-f314c44f514f', 'concept'::public.curated_course_node_type, 'Matching equations, direction fields, and candidate solution graphs', null, 2),
  ('78d84a7a-3db7-4416-8adc-0245cf3b437d', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8665de63-a7a5-47ac-9ec7-f314c44f514f', 'concept'::public.curated_course_node_type, 'Technology-assisted plots with interpretation rather than visual guesswork', null, 3),
  ('c49d4ffe-8f2c-42ee-9ed4-4abe7c3ae4bc', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'fca5fea5-bfcf-4e40-8174-17c5b1845020', 'subtopic'::public.curated_course_node_type, 'Existence, uniqueness, and validation', 'A solution method matters only when the mathematical problem is well posed and the result survives basic reality checks.', 2),
  ('2beb2608-8fe2-46d3-ac33-2e14a0f5ce12', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c49d4ffe-8f2c-42ee-9ed4-4abe7c3ae4bc', 'concept'::public.curated_course_node_type, 'Local existence and uniqueness for y''=f(t,y) under standard continuity conditions', null, 0),
  ('9ed5aaab-717e-43eb-b6f9-e7964ce72c13', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c49d4ffe-8f2c-42ee-9ed4-4abe7c3ae4bc', 'concept'::public.curated_course_node_type, 'Intervals of existence, singularities, and nonunique behavior', null, 1),
  ('5dc3e931-db8f-4ba4-a72e-ff7de2e3fd42', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c49d4ffe-8f2c-42ee-9ed4-4abe7c3ae4bc', 'concept'::public.curated_course_node_type, 'Verification by substitution and initial or boundary data', null, 2),
  ('c1104011-69c4-4868-abc1-7e6433b597bf', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c49d4ffe-8f2c-42ee-9ed4-4abe7c3ae4bc', 'concept'::public.curated_course_node_type, 'Dimensional consistency, limiting cases, signs, magnitudes, and model assumptions', null, 3),
  ('37aca794-7d47-46fc-92d1-b30bfc505b98', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'First-Order Differential Equations and Analytical Methods', 'First-order equations describe one state variable whose rate depends on time, the state, or both. Students learn a decision process for recognizing structure and selecting a method instead of treating formulas as an unconnected catalog.', 1),
  ('bc83bc3e-b992-4bad-af9c-3b449235032a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '37aca794-7d47-46fc-92d1-b30bfc505b98', 'subtopic'::public.curated_course_node_type, 'Separable equations', 'Separation isolates the variables so that antidifferentiation converts a rate law into an implicit or explicit solution.', 0),
  ('618b85dc-13d0-4829-bd62-b978155f91f2', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'bc83bc3e-b992-4bad-af9c-3b449235032a', 'concept'::public.curated_course_node_type, 'Separating variables and integrating both sides', null, 0),
  ('96c67ca9-e7be-4a83-ab46-a30bcd7afbaa', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'bc83bc3e-b992-4bad-af9c-3b449235032a', 'concept'::public.curated_course_node_type, 'Applying initial conditions and determining solution intervals', null, 1),
  ('bf1f9cb1-9be8-4996-a117-2e3600adeb99', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'bc83bc3e-b992-4bad-af9c-3b449235032a', 'concept'::public.curated_course_node_type, 'Implicit solutions, equilibrium solutions, and lost solutions', null, 2),
  ('a7bcd8d0-89ae-4f46-986a-b03569a7b2f3', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'bc83bc3e-b992-4bad-af9c-3b449235032a', 'concept'::public.curated_course_node_type, 'Growth, decay, cooling, reaction-rate, and drag models', null, 3),
  ('dae975f6-af9c-404e-aaf4-ebdfa0cb0ee8', '5948bdf7-dcf7-4f02-b49d-13d431675423', '37aca794-7d47-46fc-92d1-b30bfc505b98', 'subtopic'::public.curated_course_node_type, 'Linear equations and integrating factors', 'The integrating factor turns a first-order linear equation into a product derivative and exposes the roles of forcing and initial data.', 1),
  ('7dc19937-d34b-48d6-adfd-96615fc48ec4', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dae975f6-af9c-404e-aaf4-ebdfa0cb0ee8', 'concept'::public.curated_course_node_type, 'Standard form y''+p(t)y=g(t)', null, 0),
  ('3a5c47ff-033d-4038-95f8-89faca80990e', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dae975f6-af9c-404e-aaf4-ebdfa0cb0ee8', 'concept'::public.curated_course_node_type, 'Deriving and applying the integrating factor', null, 1),
  ('4fc2a0da-7208-4d0c-8e8c-fffce457e3f2', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dae975f6-af9c-404e-aaf4-ebdfa0cb0ee8', 'concept'::public.curated_course_node_type, 'Homogeneous response, particular response, and superposition', null, 2),
  ('f256cb26-5029-4fb1-ba19-68d7d93cd37c', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dae975f6-af9c-404e-aaf4-ebdfa0cb0ee8', 'concept'::public.curated_course_node_type, 'Mixing, circuits, pharmacokinetics, and input-output models', null, 3),
  ('98711dbc-f553-4986-8357-154ee3fd972c', '5948bdf7-dcf7-4f02-b49d-13d431675423', '37aca794-7d47-46fc-92d1-b30bfc505b98', 'subtopic'::public.curated_course_node_type, 'Exact equations and useful substitutions', 'Exactness recognizes a hidden potential function, while substitutions convert certain nonlinear equations into familiar types.', 2),
  ('d63b98d8-297a-4458-a6dd-40f0d51dfdf1', '5948bdf7-dcf7-4f02-b49d-13d431675423', '98711dbc-f553-4986-8357-154ee3fd972c', 'concept'::public.curated_course_node_type, 'Differential forms M dx + N dy = 0 and the exactness test', null, 0),
  ('84a89f18-bf1e-48c7-ac48-5d6067691c1b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '98711dbc-f553-4986-8357-154ee3fd972c', 'concept'::public.curated_course_node_type, 'Recovering a potential function and applying initial data', null, 1),
  ('db3fbf68-cecf-4eae-a7d4-34f41cfb3b15', '5948bdf7-dcf7-4f02-b49d-13d431675423', '98711dbc-f553-4986-8357-154ee3fd972c', 'concept'::public.curated_course_node_type, 'Bernoulli equations and homogeneous first-order substitutions', null, 2),
  ('b2b25142-412a-4fc3-9867-e5da6c8f882e', '5948bdf7-dcf7-4f02-b49d-13d431675423', '98711dbc-f553-4986-8357-154ee3fd972c', 'concept'::public.curated_course_node_type, 'Choosing methods through structural cues and checking the result', null, 3),
  ('a6deee43-0dfe-4253-a399-bffc036a29ab', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Autonomous Equations, Qualitative Analysis, and Nonlinear Models', 'Autonomous equations show how a system changes as a function of its current state. Their phase-line geometry often tells more about equilibria, stability, thresholds, and long-run behavior than an explicit formula does.', 2),
  ('21bb33e3-e676-409c-af7b-1c3c19cd98cc', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'a6deee43-0dfe-4253-a399-bffc036a29ab', 'subtopic'::public.curated_course_node_type, 'Phase lines and stability', 'A phase line compresses the dynamics of y''=f(y) into equilibria and arrows that describe how solutions move.', 0),
  ('90884889-d64a-410e-b44a-85c0ae15a180', '5948bdf7-dcf7-4f02-b49d-13d431675423', '21bb33e3-e676-409c-af7b-1c3c19cd98cc', 'concept'::public.curated_course_node_type, 'Equilibria and sign charts for f(y)', null, 0),
  ('9c238027-e3ef-48c7-ab94-b10dbd006bcc', '5948bdf7-dcf7-4f02-b49d-13d431675423', '21bb33e3-e676-409c-af7b-1c3c19cd98cc', 'concept'::public.curated_course_node_type, 'Stable, unstable, and semistable equilibria', null, 1),
  ('0906ef84-d20e-40fc-9dba-dd0ba722a869', '5948bdf7-dcf7-4f02-b49d-13d431675423', '21bb33e3-e676-409c-af7b-1c3c19cd98cc', 'concept'::public.curated_course_node_type, 'Basins of attraction and dependence on initial conditions', null, 2),
  ('a17a2f31-aa6a-4691-90ab-4fa1d45799b4', '5948bdf7-dcf7-4f02-b49d-13d431675423', '21bb33e3-e676-409c-af7b-1c3c19cd98cc', 'concept'::public.curated_course_node_type, 'Bifurcation awareness when a parameter changes the equilibrium pattern', null, 3),
  ('d525413f-4ecb-42f4-8c9b-0bc7067dedf6', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'a6deee43-0dfe-4253-a399-bffc036a29ab', 'subtopic'::public.curated_course_node_type, 'Canonical nonlinear models', 'Simple nonlinear laws capture saturation, competition, thresholds, and feedback that pure exponential models miss.', 1),
  ('eeda9e24-d0c4-4ecc-85c0-adf8ea382ef9', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'd525413f-4ecb-42f4-8c9b-0bc7067dedf6', 'concept'::public.curated_course_node_type, 'Logistic growth and carrying capacity', null, 0),
  ('724facce-1b24-444b-bc91-4ae025d371eb', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'd525413f-4ecb-42f4-8c9b-0bc7067dedf6', 'concept'::public.curated_course_node_type, 'Harvesting, ignition, threshold, and limited-resource models', null, 1),
  ('d2b79aee-2c08-4552-8d34-7175a0b75811', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'd525413f-4ecb-42f4-8c9b-0bc7067dedf6', 'concept'::public.curated_course_node_type, 'Compartment, mixing, reaction, and elimination models', null, 2),
  ('e149f8b7-c9ac-4f7c-9032-ec16eb55bbec', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'd525413f-4ecb-42f4-8c9b-0bc7067dedf6', 'concept'::public.curated_course_node_type, 'Nondimensionalization and interpretation of parameter groups', null, 3),
  ('bca71d13-1543-4730-9292-8b92bf7283b6', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'a6deee43-0dfe-4253-a399-bffc036a29ab', 'subtopic'::public.curated_course_node_type, 'Model calibration and critique', 'A model is an argument about mechanisms, not merely an equation, so students must connect parameters to data and limitations.', 2),
  ('81ffe84e-27e4-4d62-9264-b5d3955c3fbd', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'bca71d13-1543-4730-9292-8b92bf7283b6', 'concept'::public.curated_course_node_type, 'Estimating parameters from initial rates, equilibria, half-lives, or data', null, 0),
  ('9bd40659-1e2b-4b05-986e-90a0203437cd', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'bca71d13-1543-4730-9292-8b92bf7283b6', 'concept'::public.curated_course_node_type, 'Comparing models using residuals and qualitative behavior', null, 1),
  ('254d5af9-d39e-4c2b-add3-9865cb3ff467', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'bca71d13-1543-4730-9292-8b92bf7283b6', 'concept'::public.curated_course_node_type, 'Sensitivity to parameters and initial conditions', null, 2),
  ('d1c9a247-be44-461f-abdb-752ccb1fe9e0', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'bca71d13-1543-4730-9292-8b92bf7283b6', 'concept'::public.curated_course_node_type, 'Communicating assumptions, validity ranges, and uncertainty', null, 3),
  ('dc85ef0f-bbbe-48ff-a237-5d030c990003', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Numerical Solution of Initial-Value Problems', 'Most realistic differential equations do not have elementary closed-form solutions. Numerical methods approximate trajectories while making step size, stability, error, and verification part of the mathematical reasoning.', 3),
  ('2f6321d8-ba26-494b-81de-09ed0729e52c', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dc85ef0f-bbbe-48ff-a237-5d030c990003', 'subtopic'::public.curated_course_node_type, 'Euler and improved Euler methods', 'Euler''s method advances along local tangent lines and makes the logic of time stepping transparent.', 0),
  ('f6956152-1232-45b7-99cb-e2914cfe8080', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2f6321d8-ba26-494b-81de-09ed0729e52c', 'concept'::public.curated_course_node_type, 'Forward Euler update and geometric interpretation', null, 0),
  ('13b089e5-755a-446f-a20f-ec02e236a0df', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2f6321d8-ba26-494b-81de-09ed0729e52c', 'concept'::public.curated_course_node_type, 'Heun or midpoint methods as second-order improvements', null, 1),
  ('aa40feca-e9ba-4082-93c2-ecef4b69fe6b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2f6321d8-ba26-494b-81de-09ed0729e52c', 'concept'::public.curated_course_node_type, 'Step-size studies and global versus local truncation error', null, 2),
  ('8f88a8d2-df58-44cc-9534-e65dd75b764d', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2f6321d8-ba26-494b-81de-09ed0729e52c', 'concept'::public.curated_course_node_type, 'Failure near steep gradients, singularities, or unstable dynamics', null, 3),
  ('dd3f402a-4857-407d-bd5a-642d887d9628', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dc85ef0f-bbbe-48ff-a237-5d030c990003', 'subtopic'::public.curated_course_node_type, 'Runge-Kutta methods and solver practice', 'Runge-Kutta methods combine several slope estimates to achieve strong accuracy without higher derivatives.', 1),
  ('a47cc732-ee35-480f-975c-a78ac233058a', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dd3f402a-4857-407d-bd5a-642d887d9628', 'concept'::public.curated_course_node_type, 'Classical fourth-order Runge-Kutta structure', null, 0),
  ('067b8cb2-4563-4079-8f52-9bc67d051423', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dd3f402a-4857-407d-bd5a-642d887d9628', 'concept'::public.curated_course_node_type, 'Adaptive step size, error tolerances, and event detection', null, 1),
  ('1917ea6d-38ff-4f90-bf5c-94b9178e6b85', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dd3f402a-4857-407d-bd5a-642d887d9628', 'concept'::public.curated_course_node_type, 'Using Python, MATLAB, or Julia solvers responsibly', null, 2),
  ('b59cd292-1051-48aa-8a12-b3080fcd9368', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dd3f402a-4857-407d-bd5a-642d887d9628', 'concept'::public.curated_course_node_type, 'Reproducible plots, labeled axes, units, and solver settings', null, 3),
  ('3c4c2331-27f8-439d-9656-9775c773d0b0', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'dc85ef0f-bbbe-48ff-a237-5d030c990003', 'subtopic'::public.curated_course_node_type, 'Error, stability, and verification', 'A computed curve is evidence only after its convergence and consistency have been checked.', 2),
  ('7c6367eb-3175-43ae-aa0c-e874dd83ba31', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3c4c2331-27f8-439d-9656-9775c773d0b0', 'concept'::public.curated_course_node_type, 'Comparing against exact solutions or conserved quantities', null, 0),
  ('8967b8c4-205b-49d2-a22e-7213f05cffd9', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3c4c2331-27f8-439d-9656-9775c773d0b0', 'concept'::public.curated_course_node_type, 'Refinement studies and empirical convergence', null, 1),
  ('348e1fbc-1eda-4e62-84e1-2c3277029550', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3c4c2331-27f8-439d-9656-9775c773d0b0', 'concept'::public.curated_course_node_type, 'Numerical stability versus stability of the continuous model', null, 2),
  ('fee69b60-f661-4ca1-b8b4-2efeebad508d', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3c4c2331-27f8-439d-9656-9775c773d0b0', 'concept'::public.curated_course_node_type, 'Stiffness awareness and when explicit methods struggle', null, 3),
  ('5334f302-7048-45d6-bbd2-84f8345ac56d', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Higher-Order Linear Differential Equations', 'Higher-order linear equations govern oscillations, beams, circuits, control elements, and many reduced physical models. Their solution structure separates the system''s natural behavior from the effects of forcing.', 4),
  ('efd71e23-b2ae-4078-bcf2-0bd8c32ecc12', '5948bdf7-dcf7-4f02-b49d-13d431675423', '5334f302-7048-45d6-bbd2-84f8345ac56d', 'subtopic'::public.curated_course_node_type, 'Linear theory and solution spaces', 'The theory of linear equations explains why homogeneous solutions form a vector space and how initial data select one trajectory.', 0),
  ('65720ae2-972b-4409-a1f3-4251310cc5d8', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'efd71e23-b2ae-4078-bcf2-0bd8c32ecc12', 'concept'::public.curated_course_node_type, 'Linear differential operators and homogeneous versus nonhomogeneous equations', null, 0),
  ('82d9c545-0a91-48fd-821c-f45c5d1e2b8f', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'efd71e23-b2ae-4078-bcf2-0bd8c32ecc12', 'concept'::public.curated_course_node_type, 'Existence and uniqueness for linear initial-value problems', null, 1),
  ('2a4a2302-e614-43d4-b6b6-ede750abd6d9', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'efd71e23-b2ae-4078-bcf2-0bd8c32ecc12', 'concept'::public.curated_course_node_type, 'Linear independence, the Wronskian, and fundamental solution sets', null, 2),
