  ('c3601a2a-f7b0-43a0-97ff-66ae2aa0c317', '5948bdf7-dcf7-4f02-b49d-13d431675423', '5334f302-7048-45d6-bbd2-84f8345ac56d', 'subtopic'::public.curated_course_node_type, 'Constant-coefficient homogeneous equations', 'Characteristic roots turn differentiation into algebra and connect root structure to growth, decay, and oscillation.', 1),
  ('27aaa7e3-3c0c-44f2-9619-a7cf883e2413', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c3601a2a-f7b0-43a0-97ff-66ae2aa0c317', 'concept'::public.curated_course_node_type, 'Distinct real roots, repeated roots, and complex conjugate roots', null, 0),
  ('1be7fb54-6a62-48b0-b935-b27a31f6a9e5', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c3601a2a-f7b0-43a0-97ff-66ae2aa0c317', 'concept'::public.curated_course_node_type, 'Euler''s formula and real-valued oscillatory solutions', null, 1),
  ('e9c26d7d-87ba-4420-b633-c30d9098c65e', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c3601a2a-f7b0-43a0-97ff-66ae2aa0c317', 'concept'::public.curated_course_node_type, 'Initial-condition systems and interpretation of constants', null, 2),
  ('fbf8cec8-279b-437a-8729-73b629906ad8', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c3601a2a-f7b0-43a0-97ff-66ae2aa0c317', 'concept'::public.curated_course_node_type, 'Mechanical, electrical, and chemical examples', null, 3),
  ('8e7c477a-c6eb-4a53-85cb-1c2ebc476588', '5948bdf7-dcf7-4f02-b49d-13d431675423', '5334f302-7048-45d6-bbd2-84f8345ac56d', 'subtopic'::public.curated_course_node_type, 'Reduction of order and variable coefficients', 'When one solution is known or coefficients vary, reduction techniques extend the core linear framework.', 2),
  ('6777d4b7-d409-4b5d-b645-e9ca698cf2d6', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8e7c477a-c6eb-4a53-85cb-1c2ebc476588', 'concept'::public.curated_course_node_type, 'Reduction of order for a second independent solution', null, 0),
  ('cdb81ae1-5610-48c4-996b-7e1d56702f4f', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8e7c477a-c6eb-4a53-85cb-1c2ebc476588', 'concept'::public.curated_course_node_type, 'Cauchy-Euler equations and power-law trial forms', null, 1),
  ('b9fee554-fce0-48a9-90a5-3698c3e81d4a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8e7c477a-c6eb-4a53-85cb-1c2ebc476588', 'concept'::public.curated_course_node_type, 'Abel''s identity and qualitative information from the Wronskian', null, 2),
  ('928c5740-9501-4f9e-a1d3-9d948aa6935c', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8e7c477a-c6eb-4a53-85cb-1c2ebc476588', 'concept'::public.curated_course_node_type, 'Recognizing when numerical or series methods are more appropriate', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('3944e2c4-e1d8-4c30-8336-a0d74a6660a0', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Forced Systems, Oscillations, and Response Methods', 'Forcing introduces energy or information into a linear system. This unit connects solution methods to transient and steady-state response, damping, resonance, frequency response, and physically meaningful design decisions.', 5),
  ('e49f53f1-6d9a-4633-b442-36c618b4a133', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3944e2c4-e1d8-4c30-8336-a0d74a6660a0', 'subtopic'::public.curated_course_node_type, 'Undetermined coefficients', 'For common forcing functions, a trial response can be selected from a family preserved by differentiation.', 0),
  ('0a30a814-93b4-4e54-8b23-a774c5416bae', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'e49f53f1-6d9a-4633-b442-36c618b4a133', 'concept'::public.curated_course_node_type, 'Polynomial, exponential, sinusoidal, and combined inputs', null, 0),
  ('99a7c65d-5e1a-4f13-bfaf-7d6e7f78cbb6', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'e49f53f1-6d9a-4633-b442-36c618b4a133', 'concept'::public.curated_course_node_type, 'Trial-form selection and the modification rule for resonance', null, 1),
  ('f284b5b5-6047-47ab-b6ec-1b4ab8c44ab4', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'e49f53f1-6d9a-4633-b442-36c618b4a133', 'concept'::public.curated_course_node_type, 'Complementary and particular solutions', null, 2),
  ('918d230e-11c3-4fa3-af4a-ce09ccf85984', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'e49f53f1-6d9a-4633-b442-36c618b4a133', 'concept'::public.curated_course_node_type, 'Applicability limits when coefficients are not constant or forcing is irregular', null, 3),
  ('9cb3b4c4-2dbe-4127-b0f9-fb93f0c18a8d', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3944e2c4-e1d8-4c30-8336-a0d74a6660a0', 'subtopic'::public.curated_course_node_type, 'Variation of parameters', 'Variation of parameters constructs a particular solution from a fundamental homogeneous basis and works for much broader forcing.', 1),
  ('0b4ea23a-a705-4724-8ad9-77599c6e9c73', '5948bdf7-dcf7-4f02-b49d-13d431675423', '9cb3b4c4-2dbe-4127-b0f9-fb93f0c18a8d', 'concept'::public.curated_course_node_type, 'Deriving the parameter equations under a simplifying constraint', null, 0),
  ('ce967d8b-95ee-4841-9a66-709cfcece770', '5948bdf7-dcf7-4f02-b49d-13d431675423', '9cb3b4c4-2dbe-4127-b0f9-fb93f0c18a8d', 'concept'::public.curated_course_node_type, 'Wronskian formulas for second-order equations', null, 1),
  ('2ff07cb6-fcf3-4678-b741-1667ca19f149', '5948bdf7-dcf7-4f02-b49d-13d431675423', '9cb3b4c4-2dbe-4127-b0f9-fb93f0c18a8d', 'concept'::public.curated_course_node_type, 'Definite-integral forms that incorporate initial conditions', null, 2),
  ('ab77bed7-a1e5-47cc-83e5-49dc5b0fffa1', '5948bdf7-dcf7-4f02-b49d-13d431675423', '9cb3b4c4-2dbe-4127-b0f9-fb93f0c18a8d', 'concept'::public.curated_course_node_type, 'Comparison with Green-function and convolution ideas', null, 3),
  ('3511adb2-04b1-4c49-8d36-9df8e8476728', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3944e2c4-e1d8-4c30-8336-a0d74a6660a0', 'subtopic'::public.curated_course_node_type, 'Oscillation, damping, and resonance', 'Second-order response models show how system parameters control natural frequency, decay, amplitude, and phase.', 2),
  ('74bf787e-d8b6-4cc0-8c17-90a2c150a3d3', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3511adb2-04b1-4c49-8d36-9df8e8476728', 'concept'::public.curated_course_node_type, 'Undamped, underdamped, critically damped, and overdamped motion', null, 0),
  ('54491ba4-2d91-442c-8fbf-a3bac9afcff2', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3511adb2-04b1-4c49-8d36-9df8e8476728', 'concept'::public.curated_course_node_type, 'Driven oscillations, beats, pure resonance, and practical resonance', null, 1),
  ('5c80410e-e481-4606-9373-fc42569859e3', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3511adb2-04b1-4c49-8d36-9df8e8476728', 'concept'::public.curated_course_node_type, 'Amplitude gain, phase lag, and frequency-response curves', null, 2),
  ('664f18e7-5f8d-4d6b-989e-2a63d5be1a0b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '3511adb2-04b1-4c49-8d36-9df8e8476728', 'concept'::public.curated_course_node_type, 'Mass-spring-damper, RLC circuit, structural, and physiological analogies', null, 3),
  ('736d2e10-e654-41b3-846d-6317ba2da609', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Laplace Transforms, Impulses, and Transfer Functions', 'The Laplace transform converts differential equations into algebraic equations while handling initial data and discontinuous inputs naturally. It also introduces the language of impulse response and transfer functions used across engineering and applied science.', 6),
  ('c7bf5dfb-05d9-4199-8bab-4164d14705d4', '5948bdf7-dcf7-4f02-b49d-13d431675423', '736d2e10-e654-41b3-846d-6317ba2da609', 'subtopic'::public.curated_course_node_type, 'Transform fundamentals', 'The transform records a time-domain function as a complex-frequency representation whose algebra can simplify initial-value problems.', 0),
  ('f7359c5a-5e52-4cae-929f-dccf0726b0ae', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c7bf5dfb-05d9-4199-8bab-4164d14705d4', 'concept'::public.curated_course_node_type, 'Definition, convergence idea, linearity, and common transform pairs', null, 0),
  ('3feae66a-cf01-4f82-a13f-71e884c60cc6', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c7bf5dfb-05d9-4199-8bab-4164d14705d4', 'concept'::public.curated_course_node_type, 'First and second shifting theorems', null, 1),
  ('3bad2ffc-30c2-455c-8a4b-bc9d6c413ae4', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c7bf5dfb-05d9-4199-8bab-4164d14705d4', 'concept'::public.curated_course_node_type, 'Transforms of derivatives and incorporation of initial conditions', null, 2),
  ('ec96123d-8d3f-48d5-9bd8-42ee68eabe3a', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c7bf5dfb-05d9-4199-8bab-4164d14705d4', 'concept'::public.curated_course_node_type, 'Partial fractions and inverse transforms', null, 3),
  ('8d114d36-59c8-47f3-9839-abc41fa5ce8a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '736d2e10-e654-41b3-846d-6317ba2da609', 'subtopic'::public.curated_course_node_type, 'Steps, impulses, and convolution', 'Generalized and piecewise inputs model switches, shocks, injections, collisions, and short-duration forcing.', 1),
  ('dafb1b55-de67-4148-ab5a-6f7a8c052168', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8d114d36-59c8-47f3-9839-abc41fa5ce8a', 'concept'::public.curated_course_node_type, 'Heaviside step functions and piecewise input construction', null, 0),
  ('b3b79bbb-0d1e-45d7-88ac-95c7188755bb', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8d114d36-59c8-47f3-9839-abc41fa5ce8a', 'concept'::public.curated_course_node_type, 'Dirac delta as an idealized impulse and jump conditions', null, 1),
  ('376f60ca-5133-4240-ad0a-749dafb76ef7', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8d114d36-59c8-47f3-9839-abc41fa5ce8a', 'concept'::public.curated_course_node_type, 'Convolution and the response to a general input', null, 2),
  ('c6edbdf3-8376-47c3-9fb9-9ca06b36c4a9', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8d114d36-59c8-47f3-9839-abc41fa5ce8a', 'concept'::public.curated_course_node_type, 'Impulse response as a system fingerprint', null, 3),
  ('741a9f17-0c02-4c64-a463-99b29f264f9b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '736d2e10-e654-41b3-846d-6317ba2da609', 'subtopic'::public.curated_course_node_type, 'Transfer functions and system response', 'A transfer function links input to output and reveals stability and frequency behavior through its poles and zeros.', 2),
  ('dc388216-8062-4ce9-a039-f023a967834b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '741a9f17-0c02-4c64-a463-99b29f264f9b', 'concept'::public.curated_course_node_type, 'Zero-state and zero-input response', null, 0),
  ('2f66954f-b325-4326-be92-d14f318c5d25', '5948bdf7-dcf7-4f02-b49d-13d431675423', '741a9f17-0c02-4c64-a463-99b29f264f9b', 'concept'::public.curated_course_node_type, 'Poles, zeros, stability, and damping interpretation', null, 1),
  ('d82c3d6f-3fc8-4ed4-a8f3-89cf4e1652f1', '5948bdf7-dcf7-4f02-b49d-13d431675423', '741a9f17-0c02-4c64-a463-99b29f264f9b', 'concept'::public.curated_course_node_type, 'Block-diagram and input-output viewpoints', null, 2),
  ('75e17c67-a325-4707-95fb-62cb0761211d', '5948bdf7-dcf7-4f02-b49d-13d431675423', '741a9f17-0c02-4c64-a463-99b29f264f9b', 'concept'::public.curated_course_node_type, 'Connections to circuits, control, signal processing, transport, and pharmacokinetics', null, 3),
  ('50f393dd-0cc3-44d9-99e8-329398a20663', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Linear Systems of Differential Equations', 'Coupled systems describe interacting states and provide the natural language for multicomponent engineering, chemical, biological, and physical models. Eigenvalues and eigenvectors translate matrix structure into modes of motion.', 7),
  ('034004f8-bc0f-4ef5-a30a-6556c961052d', '5948bdf7-dcf7-4f02-b49d-13d431675423', '50f393dd-0cc3-44d9-99e8-329398a20663', 'subtopic'::public.curated_course_node_type, 'System formulation and matrix methods', 'Writing x''=Ax+g(t) exposes coupling and permits a unified treatment of many higher-order and compartment models.', 0),
  ('19a3d26e-03fc-4cb4-a49c-a3eef1c6874f', '5948bdf7-dcf7-4f02-b49d-13d431675423', '034004f8-bc0f-4ef5-a30a-6556c961052d', 'concept'::public.curated_course_node_type, 'Converting higher-order equations to first-order systems', null, 0),
  ('f069bb50-caf2-4982-a20c-deb6387720ff', '5948bdf7-dcf7-4f02-b49d-13d431675423', '034004f8-bc0f-4ef5-a30a-6556c961052d', 'concept'::public.curated_course_node_type, 'State vectors, system matrices, and equilibrium points', null, 1),
  ('5600443f-ac05-4d8f-bb19-e81142c3dea0', '5948bdf7-dcf7-4f02-b49d-13d431675423', '034004f8-bc0f-4ef5-a30a-6556c961052d', 'concept'::public.curated_course_node_type, 'Fundamental matrices and the matrix exponential', null, 2),
  ('c9003f8c-10d0-406e-a8bf-bb54f091c9fc', '5948bdf7-dcf7-4f02-b49d-13d431675423', '034004f8-bc0f-4ef5-a30a-6556c961052d', 'concept'::public.curated_course_node_type, 'Existence, uniqueness, and superposition for linear systems', null, 3),
  ('0aa6bac4-3e47-4277-b5e7-6a4eec5ab575', '5948bdf7-dcf7-4f02-b49d-13d431675423', '50f393dd-0cc3-44d9-99e8-329398a20663', 'subtopic'::public.curated_course_node_type, 'Eigenvalue solution methods', 'Eigenpairs identify invariant modes whose growth, decay, and rotation build the general solution.', 1),
  ('b2003ca4-e7d7-40b6-aec8-0f7a4e032135', '5948bdf7-dcf7-4f02-b49d-13d431675423', '0aa6bac4-3e47-4277-b5e7-6a4eec5ab575', 'concept'::public.curated_course_node_type, 'Distinct real eigenvalues and modal decomposition', null, 0),
  ('2d5af1cd-0880-4e3f-9f4d-9fa14d76b343', '5948bdf7-dcf7-4f02-b49d-13d431675423', '0aa6bac4-3e47-4277-b5e7-6a4eec5ab575', 'concept'::public.curated_course_node_type, 'Complex eigenvalues and spiral or center behavior', null, 1),
  ('f8a6a5d6-1469-4122-8a3e-5b8121f284d5', '5948bdf7-dcf7-4f02-b49d-13d431675423', '0aa6bac4-3e47-4277-b5e7-6a4eec5ab575', 'concept'::public.curated_course_node_type, 'Repeated eigenvalues, generalized eigenvectors, and defective cases', null, 2),
  ('72da4c34-1e85-4375-9786-60967672c98b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '0aa6bac4-3e47-4277-b5e7-6a4eec5ab575', 'concept'::public.curated_course_node_type, 'Forced systems and variation of constants', null, 3),
  ('2e0d7ba3-4f59-42af-ab2a-a707de6b8ca2', '5948bdf7-dcf7-4f02-b49d-13d431675423', '50f393dd-0cc3-44d9-99e8-329398a20663', 'subtopic'::public.curated_course_node_type, 'Phase portraits and applications', 'A phase portrait shows every trajectory at once, making stability and mode interaction visible.', 2),
  ('a5578a8f-4cbc-414b-ab85-7b6b01810662', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2e0d7ba3-4f59-42af-ab2a-a707de6b8ca2', 'concept'::public.curated_course_node_type, 'Nodes, saddles, spirals, centers, and direction of time', null, 0),
  ('2a03d3ed-3652-489f-8baa-f8234e796e84', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2e0d7ba3-4f59-42af-ab2a-a707de6b8ca2', 'concept'::public.curated_course_node_type, 'Trace-determinant plane for two-dimensional systems', null, 1),
  ('cf0cb250-dc20-4795-a5d4-ff97fd5ff252', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2e0d7ba3-4f59-42af-ab2a-a707de6b8ca2', 'concept'::public.curated_course_node_type, 'Coupled tanks, circuits, vibrations, kinetics, populations, and physiology', null, 2),
  ('af6850f2-99c3-4420-8710-d312d04c4c64', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2e0d7ba3-4f59-42af-ab2a-a707de6b8ca2', 'concept'::public.curated_course_node_type, 'Interpreting dominant modes, time scales, and transient behavior', null, 3),
  ('97f249ec-c7b5-4d31-87ac-c6a4fab4b563', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Nonlinear Systems, Linearization, and Stability', 'Nonlinear systems can have multiple equilibria, thresholds, cycles, and behaviors absent from linear models. Local linearization and phase-plane analysis provide a first rigorous toolkit for understanding them without requiring closed-form solutions.', 8),
  ('821a12d9-2e6e-4704-9b61-775933f19945', '5948bdf7-dcf7-4f02-b49d-13d431675423', '97f249ec-c7b5-4d31-87ac-c6a4fab4b563', 'subtopic'::public.curated_course_node_type, 'Phase-plane geometry', 'Nullclines partition the plane and help organize the direction field around equilibria and invariant regions.', 0),
  ('3f66be4f-c79f-4b77-a786-c7a9400f17c1', '5948bdf7-dcf7-4f02-b49d-13d431675423', '821a12d9-2e6e-4704-9b61-775933f19945', 'concept'::public.curated_course_node_type, 'Nullclines, equilibria, direction fields, and representative trajectories', null, 0),
  ('a043eb93-2fad-4285-a7e1-3be6d0116379', '5948bdf7-dcf7-4f02-b49d-13d431675423', '821a12d9-2e6e-4704-9b61-775933f19945', 'concept'::public.curated_course_node_type, 'Invariant sets, trapping regions, and qualitative sketches', null, 1),
  ('069fafcd-d379-4932-9c50-cbe79207cef7', '5948bdf7-dcf7-4f02-b49d-13d431675423', '821a12d9-2e6e-4704-9b61-775933f19945', 'concept'::public.curated_course_node_type, 'Conservative systems and energy-level curves', null, 2),
  ('08bda900-fc55-4a27-b3a6-3f0b5997c342', '5948bdf7-dcf7-4f02-b49d-13d431675423', '821a12d9-2e6e-4704-9b61-775933f19945', 'concept'::public.curated_course_node_type, 'Numerical phase portraits checked against analytical structure', null, 3),
  ('8891275a-9551-4144-bcea-3168ee8392be', '5948bdf7-dcf7-4f02-b49d-13d431675423', '97f249ec-c7b5-4d31-87ac-c6a4fab4b563', 'subtopic'::public.curated_course_node_type, 'Linearization and local classification', 'The Jacobian matrix gives the best local linear approximation near an equilibrium and often predicts local behavior.', 1),
  ('ac05a8c4-c372-4c3e-ba1d-45c953939f4f', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8891275a-9551-4144-bcea-3168ee8392be', 'concept'::public.curated_course_node_type, 'Jacobian evaluation at an equilibrium', null, 0),
  ('f942c9f6-86ac-487a-af9e-1de888c61297', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8891275a-9551-4144-bcea-3168ee8392be', 'concept'::public.curated_course_node_type, 'Hyperbolic equilibria and eigenvalue-based classification', null, 1),
  ('c8fb13c5-d251-45a0-afbd-e5dd8b142aee', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8891275a-9551-4144-bcea-3168ee8392be', 'concept'::public.curated_course_node_type, 'Limits of linearization at centers or zero-real-part eigenvalues', null, 2),
  ('4e672a40-e375-41e7-bba7-45a3aacddd7d', '5948bdf7-dcf7-4f02-b49d-13d431675423', '8891275a-9551-4144-bcea-3168ee8392be', 'concept'::public.curated_course_node_type, 'Local versus global stability claims', null, 3),
  ('2aaa1993-16a3-4b77-ae86-9cd763d162a3', '5948bdf7-dcf7-4f02-b49d-13d431675423', '97f249ec-c7b5-4d31-87ac-c6a4fab4b563', 'subtopic'::public.curated_course_node_type, 'Nonlinear dynamics and bifurcation awareness', 'A small parameter change can reorganize equilibria or generate sustained oscillations, so qualitative transitions matter in applications.', 2),
  ('6f8f2a99-e933-4341-8282-c89a59c6713d', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2aaa1993-16a3-4b77-ae86-9cd763d162a3', 'concept'::public.curated_course_node_type, 'Predator-prey, competition, epidemic, and autocatalytic examples', null, 0),
  ('0fac6c69-b84e-4c93-abe9-458e345b3b16', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2aaa1993-16a3-4b77-ae86-9cd763d162a3', 'concept'::public.curated_course_node_type, 'Limit cycles and self-sustained oscillation concepts', null, 1),
  ('96f83382-ce47-4358-b497-d5d3a2e802e6', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2aaa1993-16a3-4b77-ae86-9cd763d162a3', 'concept'::public.curated_course_node_type, 'Saddle-node, transcritical, and pitchfork bifurcation examples', null, 2),
  ('a53c960f-1e41-401f-9943-e0db04e918d1', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2aaa1993-16a3-4b77-ae86-9cd763d162a3', 'concept'::public.curated_course_node_type, 'Chaos as enrichment: sensitivity without overclaiming unpredictability', null, 3),
  ('1fdcc75d-cbd1-49bf-a5b4-a03c1dd57c24', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Power-Series Solutions and Special-Function Connections', 'Series methods construct local solutions near ordinary and singular points when elementary formulas fail. They also reveal why special functions appear throughout wave, diffusion, quantum, orbital, and cylindrical models.', 9),
  ('1399cbb3-a1c9-4501-9660-be6fbf3a4a93', '5948bdf7-dcf7-4f02-b49d-13d431675423', '1fdcc75d-cbd1-49bf-a5b4-a03c1dd57c24', 'subtopic'::public.curated_course_node_type, 'Power-series method at ordinary points', 'Assuming an analytic series converts a differential equation into recurrence relations for its coefficients.', 0),
  ('e976571b-5ae7-4e9a-a50c-726d6be869a4', '5948bdf7-dcf7-4f02-b49d-13d431675423', '1399cbb3-a1c9-4501-9660-be6fbf3a4a93', 'concept'::public.curated_course_node_type, 'Power series, radius of convergence, and termwise differentiation', null, 0),
  ('b554ebe6-5eb7-419e-a9c2-2e622d601bad', '5948bdf7-dcf7-4f02-b49d-13d431675423', '1399cbb3-a1c9-4501-9660-be6fbf3a4a93', 'concept'::public.curated_course_node_type, 'Index shifting and coefficient matching', null, 1),
  ('604cbe94-762d-465c-9481-878f34ca1a60', '5948bdf7-dcf7-4f02-b49d-13d431675423', '1399cbb3-a1c9-4501-9660-be6fbf3a4a93', 'concept'::public.curated_course_node_type, 'Recurrence relations and independent series solutions', null, 2),
  ('0bd4dad1-c445-4df6-9b4e-8397b9c22006', '5948bdf7-dcf7-4f02-b49d-13d431675423', '1399cbb3-a1c9-4501-9660-be6fbf3a4a93', 'concept'::public.curated_course_node_type, 'Applying initial conditions and estimating truncation error', null, 3),
  ('a8dd9946-c414-4658-ac4b-7865c8680936', '5948bdf7-dcf7-4f02-b49d-13d431675423', '1fdcc75d-cbd1-49bf-a5b4-a03c1dd57c24', 'subtopic'::public.curated_course_node_type, 'Regular singular points and Frobenius method', 'Frobenius extends power series by allowing a leading fractional or nonzero exponent near certain singular points.', 1),
  ('57d6aa21-a316-430f-bd34-27593cf241ce', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'a8dd9946-c414-4658-ac4b-7865c8680936', 'concept'::public.curated_course_node_type, 'Ordinary, regular singular, and irregular singular points', null, 0),
  ('eaa00137-757b-4620-8d09-20c8b61654a6', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'a8dd9946-c414-4658-ac4b-7865c8680936', 'concept'::public.curated_course_node_type, 'Indicial equation and characteristic exponents', null, 1),
  ('e00d6ca3-4647-4496-97c0-ca7a2c86b880', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'a8dd9946-c414-4658-ac4b-7865c8680936', 'concept'::public.curated_course_node_type, 'Root-difference cases and the possibility of logarithmic terms', null, 2),
  ('8092d37f-b711-4743-ae75-d94cdc89b21a', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'a8dd9946-c414-4658-ac4b-7865c8680936', 'concept'::public.curated_course_node_type, 'Local validity and comparison with numerical solutions', null, 3),
  ('5e8c577d-8999-4b4f-8e84-252c6780e11b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '1fdcc75d-cbd1-49bf-a5b4-a03c1dd57c24', 'subtopic'::public.curated_course_node_type, 'Special functions in applications', 'Recurring boundary geometries and coefficient patterns produce named functions that serve as reusable solution bases.', 2),
  ('b4cfcc00-2853-40a6-8917-f643c5824389', '5948bdf7-dcf7-4f02-b49d-13d431675423', '5e8c577d-8999-4b4f-8e84-252c6780e11b', 'concept'::public.curated_course_node_type, 'Bessel functions in cylindrical geometry', null, 0),
  ('45628660-2277-445e-94d8-a77577f5867a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '5e8c577d-8999-4b4f-8e84-252c6780e11b', 'concept'::public.curated_course_node_type, 'Legendre polynomials in spherical and potential problems', null, 1),
  ('18aae3ac-880d-4d14-90df-f29c66b2980a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '5e8c577d-8999-4b4f-8e84-252c6780e11b', 'concept'::public.curated_course_node_type, 'Airy, Hermite, or Laguerre functions as enrichment examples', null, 2),
  ('7919abdf-f94e-4832-ac8d-1817460af305', '5948bdf7-dcf7-4f02-b49d-13d431675423', '5e8c577d-8999-4b4f-8e84-252c6780e11b', 'concept'::public.curated_course_node_type, 'Orthogonality, normalization, and computational evaluation awareness', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('6c5021c4-0a56-4e92-8e74-2dfb15c1c36f', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Boundary-Value Problems, Eigenvalues, and Fourier Series', 'Boundary conditions constrain a solution at more than one location and often permit solutions only for special parameter values. This leads naturally to eigenvalue problems, orthogonal expansions, and Fourier representations.', 10),
  ('78ef72af-4f61-4e7d-9101-5cc2c58dbb11', '5948bdf7-dcf7-4f02-b49d-13d431675423', '6c5021c4-0a56-4e92-8e74-2dfb15c1c36f', 'subtopic'::public.curated_course_node_type, 'Linear boundary-value problems', 'Unlike an initial-value problem, a boundary-value problem may have no solution, one solution, or many solutions depending on the operator and data.', 0),
  ('24da7290-b629-450e-914c-bc713bfe9ce1', '5948bdf7-dcf7-4f02-b49d-13d431675423', '78ef72af-4f61-4e7d-9101-5cc2c58dbb11', 'concept'::public.curated_course_node_type, 'Dirichlet, Neumann, Robin, and mixed boundary conditions', null, 0),
  ('02722d18-177c-47f4-b503-89f2b1ff25d3', '5948bdf7-dcf7-4f02-b49d-13d431675423', '78ef72af-4f61-4e7d-9101-5cc2c58dbb11', 'concept'::public.curated_course_node_type, 'Shooting-method intuition and numerical boundary-value solvers', null, 1),
  ('cac24338-b251-4228-96d0-08ec3ff5c95a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '78ef72af-4f61-4e7d-9101-5cc2c58dbb11', 'concept'::public.curated_course_node_type, 'Homogeneous versus nonhomogeneous boundary data', null, 2),
  ('5effd8a6-a6df-4765-b254-34587ce27032', '5948bdf7-dcf7-4f02-b49d-13d431675423', '78ef72af-4f61-4e7d-9101-5cc2c58dbb11', 'concept'::public.curated_course_node_type, 'Solvability, uniqueness, and physical interpretation', null, 3),
  ('36869c30-43e8-4251-89bf-556a097c2854', '5948bdf7-dcf7-4f02-b49d-13d431675423', '6c5021c4-0a56-4e92-8e74-2dfb15c1c36f', 'subtopic'::public.curated_course_node_type, 'Sturm-Liouville eigenvalue problems', 'Self-adjoint boundary-value problems produce real eigenvalues and orthogonal eigenfunctions that organize solution spaces.', 1),
  ('bfb77e10-e790-456d-a767-f3f233ccb4d3', '5948bdf7-dcf7-4f02-b49d-13d431675423', '36869c30-43e8-4251-89bf-556a097c2854', 'concept'::public.curated_course_node_type, 'Operator form, weight functions, and admissible boundary conditions', null, 0),
  ('52174c3b-378c-4fa6-acfe-33e6ab986076', '5948bdf7-dcf7-4f02-b49d-13d431675423', '36869c30-43e8-4251-89bf-556a097c2854', 'concept'::public.curated_course_node_type, 'Eigenvalues, eigenfunctions, orthogonality, and normalization', null, 1),
  ('429e544d-494c-4db8-b030-fac1443ab405', '5948bdf7-dcf7-4f02-b49d-13d431675423', '36869c30-43e8-4251-89bf-556a097c2854', 'concept'::public.curated_course_node_type, 'Expansion coefficients through weighted inner products', null, 2),
  ('c09506c5-2b04-4261-b5fd-c4d984770eb3', '5948bdf7-dcf7-4f02-b49d-13d431675423', '36869c30-43e8-4251-89bf-556a097c2854', 'concept'::public.curated_course_node_type, 'Connections to vibration modes, quantum states, and diffusion modes', null, 3),
  ('c35f5270-d0e4-432d-bfb0-768c4eb9d9a2', '5948bdf7-dcf7-4f02-b49d-13d431675423', '6c5021c4-0a56-4e92-8e74-2dfb15c1c36f', 'subtopic'::public.curated_course_node_type, 'Fourier series and periodic response', 'Fourier series decompose periodic data into sinusoidal modes that linear systems process independently.', 2),
  ('a9bfd6a4-9cc1-4e8a-9226-b021896fa87e', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c35f5270-d0e4-432d-bfb0-768c4eb9d9a2', 'concept'::public.curated_course_node_type, 'Sine-cosine and complex-exponential forms', null, 0),
  ('f5ec8896-b306-441d-9e20-0b8e5ab08440', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c35f5270-d0e4-432d-bfb0-768c4eb9d9a2', 'concept'::public.curated_course_node_type, 'Even, odd, half-range, and piecewise expansions', null, 1),
  ('3c6f482c-27cd-477d-8281-0e40f17fcddc', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c35f5270-d0e4-432d-bfb0-768c4eb9d9a2', 'concept'::public.curated_course_node_type, 'Convergence, endpoint values, and Gibbs phenomenon awareness', null, 2),
  ('9d7c04b2-f5e6-4cc2-8a06-53d447c3ba6d', '5948bdf7-dcf7-4f02-b49d-13d431675423', 'c35f5270-d0e4-432d-bfb0-768c4eb9d9a2', 'concept'::public.curated_course_node_type, 'Periodic forcing and modal response of linear equations', null, 3),
  ('2878c1f3-ec79-4a42-935d-886d723620d6', '5948bdf7-dcf7-4f02-b49d-13d431675423', null, 'topic'::public.curated_course_node_type, 'Introduction to Partial Differential Equations and Separation of Variables', 'Partial differential equations describe fields that vary across both space and time. This final unit is a disciplined bridge: students classify foundational PDEs, interpret boundary and initial data, and use separation of variables without pretending to complete a full PDE course.', 11),
  ('4ba4c5db-7e0a-4fe9-a579-92a7c260967c', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2878c1f3-ec79-4a42-935d-886d723620d6', 'subtopic'::public.curated_course_node_type, 'PDE models and classification', 'The heat, wave, and Laplace equations encode diffusion, propagation, and equilibrium and illustrate distinct mathematical behaviors.', 0),
  ('3727786f-06ad-4be7-a616-f0c8bd0cd623', '5948bdf7-dcf7-4f02-b49d-13d431675423', '4ba4c5db-7e0a-4fe9-a579-92a7c260967c', 'concept'::public.curated_course_node_type, 'Deriving conservation-based heat, diffusion, and wave models', null, 0),
  ('d20d8cf7-ba26-44d0-b352-77241f9331c4', '5948bdf7-dcf7-4f02-b49d-13d431675423', '4ba4c5db-7e0a-4fe9-a579-92a7c260967c', 'concept'::public.curated_course_node_type, 'Elliptic, parabolic, and hyperbolic classification at an introductory level', null, 1),
  ('c4f07b01-8034-4c68-8cac-625e0fa97576', '5948bdf7-dcf7-4f02-b49d-13d431675423', '4ba4c5db-7e0a-4fe9-a579-92a7c260967c', 'concept'::public.curated_course_node_type, 'Initial conditions and spatial boundary conditions', null, 2),
  ('79559094-a35c-4023-bad6-d1694c035728', '5948bdf7-dcf7-4f02-b49d-13d431675423', '4ba4c5db-7e0a-4fe9-a579-92a7c260967c', 'concept'::public.curated_course_node_type, 'Well-posedness, units, and physical meaning of coefficients', null, 3),
  ('7003810b-7492-4f05-9ddb-79fc1f8b9675', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2878c1f3-ec79-4a42-935d-886d723620d6', 'subtopic'::public.curated_course_node_type, 'Separation of variables', 'A product assumption turns a linear PDE into linked ODE eigenvalue problems whose modes can be superposed.', 1),
  ('d49f27df-cfb5-4753-b5c8-2009d2b653a1', '5948bdf7-dcf7-4f02-b49d-13d431675423', '7003810b-7492-4f05-9ddb-79fc1f8b9675', 'concept'::public.curated_course_node_type, 'Product solutions and the separation constant', null, 0),
  ('6733c108-5c7f-4953-b545-430b299567e8', '5948bdf7-dcf7-4f02-b49d-13d431675423', '7003810b-7492-4f05-9ddb-79fc1f8b9675', 'concept'::public.curated_course_node_type, 'Boundary conditions selecting eigenvalues and eigenfunctions', null, 1),
  ('c7eb663c-11c1-4500-a441-2d79be1f84fb', '5948bdf7-dcf7-4f02-b49d-13d431675423', '7003810b-7492-4f05-9ddb-79fc1f8b9675', 'concept'::public.curated_course_node_type, 'Fourier coefficients from initial data', null, 2),
  ('b3e0846d-4e11-40e9-a378-730fdf87717a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '7003810b-7492-4f05-9ddb-79fc1f8b9675', 'concept'::public.curated_course_node_type, 'Heat and wave equations on a finite interval', null, 3),
  ('557e797b-9bc1-4297-8d09-b017544dfdfd', '5948bdf7-dcf7-4f02-b49d-13d431675423', '2878c1f3-ec79-4a42-935d-886d723620d6', 'subtopic'::public.curated_course_node_type, 'Modal interpretation and computational verification', 'Modal solutions explain how spatial patterns decay, oscillate, or persist and provide benchmarks for numerical simulations.', 2),
  ('8b416a3c-165d-4e44-80a9-77fb94379c5b', '5948bdf7-dcf7-4f02-b49d-13d431675423', '557e797b-9bc1-4297-8d09-b017544dfdfd', 'concept'::public.curated_course_node_type, 'Transient versus steady-state components', null, 0),
  ('71b70044-47fe-43b2-b62d-a8969c6c117a', '5948bdf7-dcf7-4f02-b49d-13d431675423', '557e797b-9bc1-4297-8d09-b017544dfdfd', 'concept'::public.curated_course_node_type, 'Mode shapes, decay rates, frequencies, and energy interpretation', null, 1),
  ('e164ce6e-1ba2-4bbf-ab8a-7bd95f440d1e', '5948bdf7-dcf7-4f02-b49d-13d431675423', '557e797b-9bc1-4297-8d09-b017544dfdfd', 'concept'::public.curated_course_node_type, 'Laplace equation and steady potential as an enrichment example', null, 2),
  ('b21de25c-72bc-410d-85c9-da4aa79ed402', '5948bdf7-dcf7-4f02-b49d-13d431675423', '557e797b-9bc1-4297-8d09-b017544dfdfd', 'concept'::public.curated_course_node_type, 'Comparing truncated series with finite-difference or solver visualizations', null, 3);
insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'textbook'::public.curated_course_resource_kind, 'Elementary Differential Equations and Boundary Value Problems', 'Wiley', 'Boyce, DiPrima, and Meade. Balanced core text for analytical methods, modeling, systems, series, numerical methods, and boundary-value problems.', 0),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'textbook'::public.curated_course_resource_kind, 'Differential Equations and Boundary Value Problems', 'Pearson', 'Edwards, Penney, and Calvis. Accessible engineering-oriented development with broad application coverage.', 1),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'textbook'::public.curated_course_resource_kind, 'Differential Equations', 'Cengage', 'Blanchard, Devaney, and Hall. Strong qualitative, numerical, and dynamical-systems viewpoint.', 2),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'textbook'::public.curated_course_resource_kind, 'Ordinary Differential Equations', 'Dover', 'Tenenbaum and Pollard. Deep problem-solving reference and historical Dover resource.', 3),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'textbook'::public.curated_course_resource_kind, 'Nonlinear Dynamics and Chaos', 'CRC Press', 'Strogatz. Excellent enrichment for phase lines, nonlinear systems, bifurcations, oscillations, and chaos.', 4),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'textbook'::public.curated_course_resource_kind, 'Mathematical Physiology', 'Springer', 'Keener and Sneyd. Biomedical enrichment for compartment, transport, feedback, and physiological models.', 5),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'website'::public.curated_course_resource_kind, 'MIT OpenCourseWare 18.03SC Differential Equations', 'https://ocw.mit.edu/courses/18-03sc-differential-equations-fall-2011/', 'Complete independent-study course with notes, videos, problems, solutions, and exams.', 6),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'website'::public.curated_course_resource_kind, 'MIT OpenCourseWare ES.1803 Differential Equations (Spring 2024)', 'https://ocw.mit.edu/courses/es-1803-differential-equations-spring-2024/', 'Recent topic notes and syllabus extending through Fourier series, PDE separation, and qualitative systems.', 7),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'website'::public.curated_course_resource_kind, 'Paul''s Online Math Notes - Differential Equations', 'https://tutorial.math.lamar.edu/Classes/DE/DE.aspx', 'Concise explanations and worked practice for standard ODE methods.', 8),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'website'::public.curated_course_resource_kind, 'LibreTexts Differential Equations', 'https://math.libretexts.org/Bookshelves/Differential_Equations', 'Open textbooks covering analytical, numerical, systems, and modeling topics.', 9),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'website'::public.curated_course_resource_kind, 'Khan Academy Differential Equations', 'https://www.khanacademy.org/math/differential-equations', 'Guided review and practice for foundational solution techniques and transforms.', 10),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'website'::public.curated_course_resource_kind, 'UC Berkeley Math 54', 'https://math.berkeley.edu/courses/choosing/lowerdivlist/math54', 'Useful benchmark for the linear-algebra, systems, eigenvalue, and Fourier connections.', 11),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'website'::public.curated_course_resource_kind, 'Python: SciPy solve_ivp and solve_bvp', 'https://docs.scipy.org/doc/scipy/reference/generated/scipy.integrate.solve_ivp.html', 'Open numerical IVP/BVP solvers. Pair with NumPy, Matplotlib, and SymPy for verification. Also https://docs.scipy.org/doc/scipy/reference/generated/scipy.integrate.solve_bvp.html.', 12),
  ('5948bdf7-dcf7-4f02-b49d-13d431675423', 'website'::public.curated_course_resource_kind, 'MATLAB ODE solvers', 'https://www.mathworks.com/help/matlab/ordinary-differential-equations.html', 'Widely used engineering solver family with event handling and stiff-system options.', 13),
